// ─── scripted clock: colyseus_room_clock_now_provider override ──────────────

var NOW: f64 = 0;
fn scriptedNow() callconv(.c) f64 {
    return NOW;
}

fn useScriptedNow() void {
    NOW = 0;
    c.colyseus_room_clock_now_provider = scriptedNow;
}

// ─── stub send/is_open/get_clock host for direct handle tests ───────────────

var sent_frames: [16][64]u8 = undefined;
var sent_lens: [16]usize = undefined;
var sent_count: usize = 0;
var stub_clock: ?*c.colyseus_room_clock_t = null;

fn stubSend(data: [*c]const u8, length: usize, userdata: ?*anyopaque) callconv(.c) void {
    _ = userdata;
    if (sent_count < sent_frames.len and length <= 64) {
        @memcpy(sent_frames[sent_count][0..length], data[0..length]);
        sent_lens[sent_count] = length;
        sent_count += 1;
    }
}

fn stubIsOpen(userdata: ?*anyopaque) callconv(.c) bool {
    _ = userdata;
    return true;
}

fn stubGetClock(userdata: ?*anyopaque) callconv(.c) ?*c.colyseus_room_clock_t {
    _ = userdata;
    return stub_clock;
}

fn expectFrame(index: usize, expected: []const u8) !void {
    try testing.expectEqual(expected.len, sent_lens[index]);
    try testing.expectEqualSlices(u8, expected, sent_frames[index][0..sent_lens[index]]);
}

const HandleCtx = struct {
    instance: *c.move_input_t,
    handle: *c.colyseus_input_handle_t,
};

fn makeHandle(unreliable: bool, stamp_render: bool, stamp_reckon: bool, render_delay: f64) HandleCtx {
    sent_count = 0;
    const instance = c.move_input_create().?;
    instance.*.__base.__vtable = &c.move_input_vtable;
    const encoder = c.colyseus_input_encoder_create(
        @ptrCast(instance), &c.move_input_vtable, unreliable, 3).?;
    var options = std.mem.zeroes(c.colyseus_input_options_t);
    options.render_delay = render_delay;
    const handle = c.colyseus_input_handle_create(
        @ptrCast(instance), &c.move_input_vtable, encoder,
        stamp_render, stamp_reckon, &options, 0, 0, 0,
        stubSend, stubIsOpen, stubGetClock, null).?;
    return .{ .instance = instance, .handle = handle };
}

fn destroyHandle(ctx: HandleCtx) void {
    // The handle owns the bound instance (see colyseus_input_handle_free) —
    // destroying it here too is a double free. Older allocators let that slide;
    // macOS 15's hardened xzone malloc traps on it.
    c.colyseus_input_handle_free(ctx.handle);
}

/// Seed a real clock into an exactly-scripted state: one sample at tNow=1000
/// with sNow=500, rtt=80 → offset = 500+40−1000 = −460 (exact), smoothedRtt =
/// 80 (seed), lastServerTime = 500 > 0 (synced). serverNow(T) = T − 460.
fn makeSyncedClock() *c.colyseus_room_clock_t {
    const clock = c.colyseus_room_clock_create().?;
    NOW = 1000;
    c.colyseus_room_clock_sample(clock, 500, 80);
    return clock;
}

// ─── encoder ────────────────────────────────────────────────────────────────

test "input_encoder_reliable" {
    const instance = c.move_input_create().?;
    defer c.move_input_vtable.destroy.?(@ptrCast(instance));
    const encoder = c.colyseus_input_encoder_create(
        @ptrCast(instance), &c.move_input_vtable, false, 0).?;
    defer c.colyseus_input_encoder_free(encoder);

    var out_len: usize = 0;

    instance.*.vx = 1.5;
    instance.*.vy = -2;
    instance.*.jump = true;
    instance.*.action = 3;
    var out = c.colyseus_input_encoder_encode(encoder, &out_len);
    try testing.expectEqualSlices(u8, &[_]u8{ 128, 202, 0, 0, 192, 63, 129, 254, 130, 1, 131, 3 }, out[0..out_len]);

    instance.*.vx = 2.5;
    out = c.colyseus_input_encoder_encode(encoder, &out_len);
    try testing.expectEqualSlices(u8, &[_]u8{ 128, 202, 0, 0, 32, 64 }, out[0..out_len]);

    // no change → empty body
    out = c.colyseus_input_encoder_encode(encoder, &out_len);
    try testing.expectEqual(@as(usize, 0), out_len);

    instance.*.jump = false;
    instance.*.action = 7;
    out = c.colyseus_input_encoder_encode(encoder, &out_len);
    try testing.expectEqualSlices(u8, &[_]u8{ 130, 0, 131, 7 }, out[0..out_len]);

    // reset → full snapshot of populated fields
    c.colyseus_input_encoder_reset(encoder);
    out = c.colyseus_input_encoder_encode(encoder, &out_len);
    try testing.expectEqualSlices(u8, &[_]u8{ 128, 202, 0, 0, 32, 64, 129, 254, 130, 0, 131, 7 }, out[0..out_len]);
}

test "input_encoder_unreliable" {
    const instance = c.move_input_create().?;
    defer c.move_input_vtable.destroy.?(@ptrCast(instance));
    const encoder = c.colyseus_input_encoder_create(
        @ptrCast(instance), &c.move_input_vtable, true, 3).?;
    defer c.colyseus_input_encoder_free(encoder);

    var out_len: usize = 0;

    instance.*.vx = 1.5;
    instance.*.vy = -2;
    instance.*.jump = true;
    instance.*.action = 3;
    var out = c.colyseus_input_encoder_encode(encoder, &out_len);
    try testing.expectEqualSlices(u8, &[_]u8{ 1, 12, 128, 202, 0, 0, 192, 63, 129, 254, 130, 1, 131, 3 }, out[0..out_len]);
    try testing.expectEqual(@as(c_int, 1), c.colyseus_input_encoder_seq(encoder));

    instance.*.vx = 2.5;
    out = c.colyseus_input_encoder_encode(encoder, &out_len);
    try testing.expectEqualSlices(u8, &[_]u8{ 1, 12, 128, 202, 0, 0, 192, 63, 129, 254, 130, 1, 131, 3, 6, 128, 202, 0, 0, 32, 64 }, out[0..out_len]);

    // no change → carry-forward empty slot, ring re-emitted
    out = c.colyseus_input_encoder_encode(encoder, &out_len);
    try testing.expectEqualSlices(u8, &[_]u8{ 1, 12, 128, 202, 0, 0, 192, 63, 129, 254, 130, 1, 131, 3, 6, 128, 202, 0, 0, 32, 64, 0 }, out[0..out_len]);

    instance.*.vy = 9;
    out = c.colyseus_input_encoder_encode(encoder, &out_len);
    try testing.expectEqualSlices(u8, &[_]u8{ 2, 6, 128, 202, 0, 0, 32, 64, 0, 2, 129, 9 }, out[0..out_len]);
    try testing.expectEqual(@as(c_int, 4), c.colyseus_input_encoder_seq(encoder));
}

// ─── handle framing ─────────────────────────────────────────────────────────

test "handle_reliable_no_stamp" {
    useScriptedNow();
    const ctx = makeHandle(false, false, false, 0);
    defer destroyHandle(ctx);

    ctx.instance.*.vx = 1.5;
    ctx.instance.*.vy = -2;
    ctx.instance.*.jump = true;
    ctx.instance.*.action = 3;
    try testing.expectEqual(@as(c_int, 1), c.colyseus_input_handle_send(ctx.handle));
    ctx.instance.*.vx = 2.5;
    try testing.expectEqual(@as(c_int, 2), c.colyseus_input_handle_send(ctx.handle));
    try testing.expectEqual(@as(c_int, 3), c.colyseus_input_handle_send(ctx.handle)); // body-less [19]

    try testing.expectEqual(@as(c_int, 3), c.colyseus_input_handle_sent_count(ctx.handle));
    try expectFrame(0, &[_]u8{ 19, 128, 202, 0, 0, 192, 63, 129, 254, 130, 1, 131, 3 });
    try expectFrame(1, &[_]u8{ 19, 128, 202, 0, 0, 32, 64 });
    try expectFrame(2, &[_]u8{19});
}

test "handle_reliable_stamped_both" {
    useScriptedNow();
    const clock = makeSyncedClock(); // serverNow(T) = T − 460; smoothedRtt 80
    defer c.colyseus_room_clock_free(clock);
    stub_clock = clock;

    const ctx = makeHandle(false, true, true, 50); // renderDelta = 50+40 = 90
    defer destroyHandle(ctx);

    NOW = 1460; // serverNow = 1000
    ctx.instance.*.vx = 1.5;
    _ = c.colyseus_input_handle_send(ctx.handle);
    NOW = 1476.7; // serverNow = 1016.7 → stamp 1017
    ctx.instance.*.vx = 2;
    _ = c.colyseus_input_handle_send(ctx.handle);
    NOW = 1493.4; // serverNow = 1033.4 → stamp 1033
    _ = c.colyseus_input_handle_send(ctx.handle);

    // [19|0x80][varint Δreckon][uint16 renderDelta=90][delta body]
    try expectFrame(0, &[_]u8{ 147, 205, 232, 3, 90, 0, 128, 202, 0, 0, 192, 63 });
    try expectFrame(1, &[_]u8{ 147, 17, 90, 0, 128, 2 });
    try expectFrame(2, &[_]u8{ 147, 16, 90, 0 });

    try testing.expectEqual(@as(f64, 1000), c.colyseus_input_handle_reckon_time_at(ctx.handle, 1));
    try testing.expectEqual(@as(f64, 1017), c.colyseus_input_handle_reckon_time_at(ctx.handle, 2));
    try testing.expectEqual(@as(f64, 1033), c.colyseus_input_handle_reckon_time_at(ctx.handle, 3));
}

